// Priority chains of the conditional operator, 4 to 32 levels deep, with
// 0, 1, X and Z predicates at every position (IEEE 1800-2009 11.4.11).
`timescale 1ns/1ns
module tb;
  logic [3:0] s4;
  logic [31:0] d4 [5];
  wire [31:0] w4 = s4[0] ? d4[0] : s4[1] ? d4[1] : s4[2] ? d4[2] : s4[3] ? d4[3] : d4[4];
  logic [31:0] p4;
  function automatic logic [31:0] f4(logic [3:0] s);
    return s[0] ? d4[0] : s[1] ? d4[1] : s[2] ? d4[2] : s[3] ? d4[3] : d4[4];
  endfunction
  bit [3:0] b4;
  int t4;
  task automatic calc4();
    p4 = s4[0] ? d4[0] : s4[1] ? d4[1] : s4[2] ? d4[2] : s4[3] ? d4[3] : d4[4];
  endtask
  logic [7:0] s8;
  logic [31:0] d8 [9];
  wire [31:0] w8 = s8[0] ? d8[0] : s8[1] ? d8[1] : s8[2] ? d8[2] : s8[3] ? d8[3] : s8[4] ? d8[4] : s8[5] ? d8[5] : s8[6] ? d8[6] : s8[7] ? d8[7] : d8[8];
  logic [31:0] p8;
  function automatic logic [31:0] f8(logic [7:0] s);
    return s[0] ? d8[0] : s[1] ? d8[1] : s[2] ? d8[2] : s[3] ? d8[3] : s[4] ? d8[4] : s[5] ? d8[5] : s[6] ? d8[6] : s[7] ? d8[7] : d8[8];
  endfunction
  bit [7:0] b8;
  int t8;
  task automatic calc8();
    p8 = s8[0] ? d8[0] : s8[1] ? d8[1] : s8[2] ? d8[2] : s8[3] ? d8[3] : s8[4] ? d8[4] : s8[5] ? d8[5] : s8[6] ? d8[6] : s8[7] ? d8[7] : d8[8];
  endtask
  logic [15:0] s16;
  logic [31:0] d16 [17];
  wire [31:0] w16 = s16[0] ? d16[0] : s16[1] ? d16[1] : s16[2] ? d16[2] : s16[3] ? d16[3] : s16[4] ? d16[4] : s16[5] ? d16[5] : s16[6] ? d16[6] : s16[7] ? d16[7] : s16[8] ? d16[8] : s16[9] ? d16[9] : s16[10] ? d16[10] : s16[11] ? d16[11] : s16[12] ? d16[12] : s16[13] ? d16[13] : s16[14] ? d16[14] : s16[15] ? d16[15] : d16[16];
  logic [31:0] p16;
  function automatic logic [31:0] f16(logic [15:0] s);
    return s[0] ? d16[0] : s[1] ? d16[1] : s[2] ? d16[2] : s[3] ? d16[3] : s[4] ? d16[4] : s[5] ? d16[5] : s[6] ? d16[6] : s[7] ? d16[7] : s[8] ? d16[8] : s[9] ? d16[9] : s[10] ? d16[10] : s[11] ? d16[11] : s[12] ? d16[12] : s[13] ? d16[13] : s[14] ? d16[14] : s[15] ? d16[15] : d16[16];
  endfunction
  bit [15:0] b16;
  int t16;
  task automatic calc16();
    p16 = s16[0] ? d16[0] : s16[1] ? d16[1] : s16[2] ? d16[2] : s16[3] ? d16[3] : s16[4] ? d16[4] : s16[5] ? d16[5] : s16[6] ? d16[6] : s16[7] ? d16[7] : s16[8] ? d16[8] : s16[9] ? d16[9] : s16[10] ? d16[10] : s16[11] ? d16[11] : s16[12] ? d16[12] : s16[13] ? d16[13] : s16[14] ? d16[14] : s16[15] ? d16[15] : d16[16];
  endtask
  logic [31:0] s32;
  logic [31:0] d32 [33];
  wire [31:0] w32 = s32[0] ? d32[0] : s32[1] ? d32[1] : s32[2] ? d32[2] : s32[3] ? d32[3] : s32[4] ? d32[4] : s32[5] ? d32[5] : s32[6] ? d32[6] : s32[7] ? d32[7] : s32[8] ? d32[8] : s32[9] ? d32[9] : s32[10] ? d32[10] : s32[11] ? d32[11] : s32[12] ? d32[12] : s32[13] ? d32[13] : s32[14] ? d32[14] : s32[15] ? d32[15] : s32[16] ? d32[16] : s32[17] ? d32[17] : s32[18] ? d32[18] : s32[19] ? d32[19] : s32[20] ? d32[20] : s32[21] ? d32[21] : s32[22] ? d32[22] : s32[23] ? d32[23] : s32[24] ? d32[24] : s32[25] ? d32[25] : s32[26] ? d32[26] : s32[27] ? d32[27] : s32[28] ? d32[28] : s32[29] ? d32[29] : s32[30] ? d32[30] : s32[31] ? d32[31] : d32[32];
  logic [31:0] p32;
  function automatic logic [31:0] f32(logic [31:0] s);
    return s[0] ? d32[0] : s[1] ? d32[1] : s[2] ? d32[2] : s[3] ? d32[3] : s[4] ? d32[4] : s[5] ? d32[5] : s[6] ? d32[6] : s[7] ? d32[7] : s[8] ? d32[8] : s[9] ? d32[9] : s[10] ? d32[10] : s[11] ? d32[11] : s[12] ? d32[12] : s[13] ? d32[13] : s[14] ? d32[14] : s[15] ? d32[15] : s[16] ? d32[16] : s[17] ? d32[17] : s[18] ? d32[18] : s[19] ? d32[19] : s[20] ? d32[20] : s[21] ? d32[21] : s[22] ? d32[22] : s[23] ? d32[23] : s[24] ? d32[24] : s[25] ? d32[25] : s[26] ? d32[26] : s[27] ? d32[27] : s[28] ? d32[28] : s[29] ? d32[29] : s[30] ? d32[30] : s[31] ? d32[31] : d32[32];
  endfunction
  bit [31:0] b32;
  int t32;
  task automatic calc32();
    p32 = s32[0] ? d32[0] : s32[1] ? d32[1] : s32[2] ? d32[2] : s32[3] ? d32[3] : s32[4] ? d32[4] : s32[5] ? d32[5] : s32[6] ? d32[6] : s32[7] ? d32[7] : s32[8] ? d32[8] : s32[9] ? d32[9] : s32[10] ? d32[10] : s32[11] ? d32[11] : s32[12] ? d32[12] : s32[13] ? d32[13] : s32[14] ? d32[14] : s32[15] ? d32[15] : s32[16] ? d32[16] : s32[17] ? d32[17] : s32[18] ? d32[18] : s32[19] ? d32[19] : s32[20] ? d32[20] : s32[21] ? d32[21] : s32[22] ? d32[22] : s32[23] ? d32[23] : s32[24] ? d32[24] : s32[25] ? d32[25] : s32[26] ? d32[26] : s32[27] ? d32[27] : s32[28] ? d32[28] : s32[29] ? d32[29] : s32[30] ? d32[30] : s32[31] ? d32[31] : d32[32];
  endtask
  task automatic show(string what, int n, int pos, logic [31:0] w, logic [31:0] p, logic [31:0] f);
    $display("%s n=%0d pos=%0d w=%h p=%h f=%h", what, n, pos, w, p, f);
  endtask
  initial begin
    for (int i = 0; i <= 4; i++) d4[i] = 32'hc3a50000 ^ (32'h00010101 * (i + 1));
    for (int pos = 0; pos < 4; pos++) begin
      s4 = '0; s4[pos] = 1'b1; calc4();
      #1 show("one", 4, pos, w4, p4, f4(s4));
      s4 = '0; s4[pos] = 1'bx; calc4();
      #1 show("x", 4, pos, w4, p4, f4(s4));
      s4 = '0; s4[pos] = 1'bz; calc4();
      #1 show("z", 4, pos, w4, p4, f4(s4));
      s4 = '0; s4[pos] = 1'bx; s4[3] = (pos == 3) ? 1'bx : 1'b1; calc4();
      #1 show("x1", 4, pos, w4, p4, f4(s4));
      s4 = '0; s4[pos] = 1'bx; s4[(pos + 2) % 4] = 1'bz; calc4();
      #1 show("xx", 4, pos, w4, p4, f4(s4));
      b4 = '0; b4[pos] = 1'b1;
      t4 = b4[0] ? 0 * 3 + 1 : b4[1] ? 1 * 3 + 1 : b4[2] ? 2 * 3 + 1 : b4[3] ? 3 * 3 + 1 : -1;
      $display("two n=4 pos=%0d t=%0d", pos, t4);
    end
    s4 = '0; #1 show("none", 4, 0, w4, p4, f4(s4));
    s4 = 'x; calc4();
    #1 show("allx", 4, 0, w4, p4, f4(s4));
    for (int i = 0; i <= 4; i++) d4[i] = 32'h0f0f1234;
    calc4();
    #1 show("same", 4, 0, w4, p4, f4(s4));
    for (int i = 0; i <= 8; i++) d8[i] = 32'hc3a50000 ^ (32'h00010101 * (i + 1));
    for (int pos = 0; pos < 8; pos++) begin
      s8 = '0; s8[pos] = 1'b1; calc8();
      #1 show("one", 8, pos, w8, p8, f8(s8));
      s8 = '0; s8[pos] = 1'bx; calc8();
      #1 show("x", 8, pos, w8, p8, f8(s8));
      s8 = '0; s8[pos] = 1'bz; calc8();
      #1 show("z", 8, pos, w8, p8, f8(s8));
      s8 = '0; s8[pos] = 1'bx; s8[7] = (pos == 7) ? 1'bx : 1'b1; calc8();
      #1 show("x1", 8, pos, w8, p8, f8(s8));
      s8 = '0; s8[pos] = 1'bx; s8[(pos + 2) % 8] = 1'bz; calc8();
      #1 show("xx", 8, pos, w8, p8, f8(s8));
      b8 = '0; b8[pos] = 1'b1;
      t8 = b8[0] ? 0 * 3 + 1 : b8[1] ? 1 * 3 + 1 : b8[2] ? 2 * 3 + 1 : b8[3] ? 3 * 3 + 1 : b8[4] ? 4 * 3 + 1 : b8[5] ? 5 * 3 + 1 : b8[6] ? 6 * 3 + 1 : b8[7] ? 7 * 3 + 1 : -1;
      $display("two n=8 pos=%0d t=%0d", pos, t8);
    end
    s8 = '0; #1 show("none", 8, 0, w8, p8, f8(s8));
    s8 = 'x; calc8();
    #1 show("allx", 8, 0, w8, p8, f8(s8));
    for (int i = 0; i <= 8; i++) d8[i] = 32'h0f0f1234;
    calc8();
    #1 show("same", 8, 0, w8, p8, f8(s8));
    for (int i = 0; i <= 16; i++) d16[i] = 32'hc3a50000 ^ (32'h00010101 * (i + 1));
    for (int pos = 0; pos < 16; pos++) begin
      s16 = '0; s16[pos] = 1'b1; calc16();
      #1 show("one", 16, pos, w16, p16, f16(s16));
      s16 = '0; s16[pos] = 1'bx; calc16();
      #1 show("x", 16, pos, w16, p16, f16(s16));
      s16 = '0; s16[pos] = 1'bz; calc16();
      #1 show("z", 16, pos, w16, p16, f16(s16));
      s16 = '0; s16[pos] = 1'bx; s16[15] = (pos == 15) ? 1'bx : 1'b1; calc16();
      #1 show("x1", 16, pos, w16, p16, f16(s16));
      s16 = '0; s16[pos] = 1'bx; s16[(pos + 2) % 16] = 1'bz; calc16();
      #1 show("xx", 16, pos, w16, p16, f16(s16));
      b16 = '0; b16[pos] = 1'b1;
      t16 = b16[0] ? 0 * 3 + 1 : b16[1] ? 1 * 3 + 1 : b16[2] ? 2 * 3 + 1 : b16[3] ? 3 * 3 + 1 : b16[4] ? 4 * 3 + 1 : b16[5] ? 5 * 3 + 1 : b16[6] ? 6 * 3 + 1 : b16[7] ? 7 * 3 + 1 : b16[8] ? 8 * 3 + 1 : b16[9] ? 9 * 3 + 1 : b16[10] ? 10 * 3 + 1 : b16[11] ? 11 * 3 + 1 : b16[12] ? 12 * 3 + 1 : b16[13] ? 13 * 3 + 1 : b16[14] ? 14 * 3 + 1 : b16[15] ? 15 * 3 + 1 : -1;
      $display("two n=16 pos=%0d t=%0d", pos, t16);
    end
    s16 = '0; #1 show("none", 16, 0, w16, p16, f16(s16));
    s16 = 'x; calc16();
    #1 show("allx", 16, 0, w16, p16, f16(s16));
    for (int i = 0; i <= 16; i++) d16[i] = 32'h0f0f1234;
    calc16();
    #1 show("same", 16, 0, w16, p16, f16(s16));
    for (int i = 0; i <= 32; i++) d32[i] = 32'hc3a50000 ^ (32'h00010101 * (i + 1));
    for (int pos = 0; pos < 32; pos++) begin
      s32 = '0; s32[pos] = 1'b1; calc32();
      #1 show("one", 32, pos, w32, p32, f32(s32));
      s32 = '0; s32[pos] = 1'bx; calc32();
      #1 show("x", 32, pos, w32, p32, f32(s32));
      s32 = '0; s32[pos] = 1'bz; calc32();
      #1 show("z", 32, pos, w32, p32, f32(s32));
      s32 = '0; s32[pos] = 1'bx; s32[31] = (pos == 31) ? 1'bx : 1'b1; calc32();
      #1 show("x1", 32, pos, w32, p32, f32(s32));
      s32 = '0; s32[pos] = 1'bx; s32[(pos + 2) % 32] = 1'bz; calc32();
      #1 show("xx", 32, pos, w32, p32, f32(s32));
      b32 = '0; b32[pos] = 1'b1;
      t32 = b32[0] ? 0 * 3 + 1 : b32[1] ? 1 * 3 + 1 : b32[2] ? 2 * 3 + 1 : b32[3] ? 3 * 3 + 1 : b32[4] ? 4 * 3 + 1 : b32[5] ? 5 * 3 + 1 : b32[6] ? 6 * 3 + 1 : b32[7] ? 7 * 3 + 1 : b32[8] ? 8 * 3 + 1 : b32[9] ? 9 * 3 + 1 : b32[10] ? 10 * 3 + 1 : b32[11] ? 11 * 3 + 1 : b32[12] ? 12 * 3 + 1 : b32[13] ? 13 * 3 + 1 : b32[14] ? 14 * 3 + 1 : b32[15] ? 15 * 3 + 1 : b32[16] ? 16 * 3 + 1 : b32[17] ? 17 * 3 + 1 : b32[18] ? 18 * 3 + 1 : b32[19] ? 19 * 3 + 1 : b32[20] ? 20 * 3 + 1 : b32[21] ? 21 * 3 + 1 : b32[22] ? 22 * 3 + 1 : b32[23] ? 23 * 3 + 1 : b32[24] ? 24 * 3 + 1 : b32[25] ? 25 * 3 + 1 : b32[26] ? 26 * 3 + 1 : b32[27] ? 27 * 3 + 1 : b32[28] ? 28 * 3 + 1 : b32[29] ? 29 * 3 + 1 : b32[30] ? 30 * 3 + 1 : b32[31] ? 31 * 3 + 1 : -1;
      $display("two n=32 pos=%0d t=%0d", pos, t32);
    end
    s32 = '0; #1 show("none", 32, 0, w32, p32, f32(s32));
    s32 = 'x; calc32();
    #1 show("allx", 32, 0, w32, p32, f32(s32));
    for (int i = 0; i <= 32; i++) d32[i] = 32'h0f0f1234;
    calc32();
    #1 show("same", 32, 0, w32, p32, f32(s32));
  end
endmodule
